PANTHEON_GAMMA_CATEGORIES = {
    "medicine": {"name": "Medicine & Health", "agents": MEDICINE_AGENTS, "color": "#DC2626"},
    "astronomy": {"name": "Astronomy & Space", "agents": ASTRONOMY_AGENTS, "color": "#F59E0B"},
    "oceanography": {"name": "Oceanography & Marine Science", "agents": OCEANOGRAPHY_AGENTS, "color": "#0284C7"},
    "meteorology": {"name": "Meteorology & Climate", "agents": METEOROLOGY_AGENTS, "color": "#475569"},
}

def get_all_pantheon_gamma_agents() -> list:
    agents = []
    for cat_id, cat in PANTHEON_GAMMA_CATEGORIES.items():
        for agent in cat["agents"]:
            agents.append({"id": agent["id"], "name": agent["name"], "role": agent["role"], "specialty": agent["specialty"], "color": agent["color"], "category": cat_id, "category_name": cat["name"]})
    return agents

def get_pantheon_gamma_prompt(agent_id: str, context: str) -> tuple:
    for cat_id, cat in PANTHEON_GAMMA_CATEGORIES.items():
        for agent in cat["agents"]:
            if agent["id"] == agent_id:
                return (f"{agent['persona']}\n\nYou are part of the Expert Pantheon (Gamma Division).", f"As {agent['name']} ({agent['role']}), apply your expertise to:\n\n{context}")
    return ("You are a domain expert.", f"Analyze: {context}")
